package com.example.riskplatform.service;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.example.riskplatform.entity.*;import com.example.riskplatform.mapper.*;import com.fasterxml.jackson.databind.ObjectMapper;import lombok.RequiredArgsConstructor;import com.example.riskplatform.service.rag.CorpusEvents;import org.springframework.stereotype.Service;import java.math.*;import java.util.*;
@Service @RequiredArgsConstructor public class RiskEngineService{private final MetricMapper mm;private final RiskRuleMapper rm;private final RiskEventMapper em;private final ObjectMapper om;private final CorpusEvents corpus;public void evaluateMetric(Long id){Metric m=mm.selectById(id);if(m==null)return;List<RiskRule>rs=rm.selectList(new LambdaQueryWrapper<RiskRule>().eq(RiskRule::getMetricCode,m.getMetricCode()).eq(RiskRule::getEnabled,1));for(RiskRule r:rs)if(hit(m,r))create(m,r);}private boolean hit(Metric m,RiskRule r){BigDecimal v=m.getMetricValue(),t=r.getThresholdValue();if(v==null||t==null)return false;return switch(r.getOperatorCode()){case "GT"->v.compareTo(t)>0;case "GE"->v.compareTo(t)>=0;case "LT"->v.compareTo(t)<0;case "LE"->v.compareTo(t)<=0;case "CHANGE_GT","CHANGE_LT"->change(m,r);default->false;};}private boolean change(Metric m,RiskRule r){List<Metric>p=mm.selectList(new LambdaQueryWrapper<Metric>().eq(Metric::getCompanyId,m.getCompanyId()).eq(Metric::getMetricCode,m.getMetricCode()).lt(Metric::getMetricDate,m.getMetricDate()).orderByDesc(Metric::getMetricDate).last("LIMIT 1"));if(p.isEmpty()||p.get(0).getMetricValue().compareTo(BigDecimal.ZERO)==0)return false;BigDecimal c=m.getMetricValue().subtract(p.get(0).getMetricValue()).divide(p.get(0).getMetricValue().abs(),4,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100));return "CHANGE_GT".equals(r.getOperatorCode())?c.compareTo(r.getThresholdValue())>0:c.compareTo(r.getThresholdValue().negate())<0;}private void create(Metric m,RiskRule r){Long n=em.selectCount(new LambdaQueryWrapper<RiskEvent>().eq(RiskEvent::getCompanyId,m.getCompanyId()).eq(RiskEvent::getRuleId,r.getId()).eq(RiskEvent::getMetricDate,m.getMetricDate()));if(n>0)return;RiskEvent e=new RiskEvent();e.setEventNo("RISK-"+System.currentTimeMillis()+"-"+r.getId());e.setCompanyId(m.getCompanyId());e.setRuleId(r.getId());e.setRiskType(r.getRiskType());e.setRiskTitle(r.getRuleName());e.setRiskLevel(r.getRiskLevel());e.setStatus("OPEN");e.setTriggerValue(m.getMetricValue());e.setThresholdValue(r.getThresholdValue());e.setMetricDate(m.getMetricDate());try{e.setEvidenceJson(om.writeValueAsString(Map.of("metricId",m.getId(),"metricCode",m.getMetricCode(),"metricName",m.getMetricName(),"value",m.getMetricValue())));}catch(Exception ignored){}em.insert(e);corpus.upsert("event",e.getId(),e.getCompanyId());corpus.aggregate(e.getCompanyId());}}
